            cache.pop(k, None)

    for event in events:
        current_time = event["time"]
        evict_expired(current_time)
        key = event["key"]

        if event["op"] == "put":
            if capacity == 0:
                continue
            cache.pop(key, None)
            cache[key] = (event["value"], current_time + event["ttl"])
