                cache.popitem(last=False)
        elif event["op"] == "get":
            if key not in cache:
                results.append(None)
                continue
            value, _ = cache[key]
            cache.move_to_end(key)
            results.append(value)
        else:
            raise ValueError(f"unknown op: {event['op']}")

